    exampleCase: "https://goodcase.ai/cases/seedance-create-a-30-second-1080p-ultra-realistic-korean-subway-action-comedy-scene-usi-93b40e9db5b1",
    docsUrl: "https://github.com/LearnPrompt/awesome-seedance/blob/main/docs/templates/zh/meme-comedy.md",
